export interface FunctionTool<Input = any, Output = any> {
    type?: "function";
    input: Input;
    output: Output;
}
export interface DynamicTool<Input = any, Output = any> {
    type: "dynamic";
    input: Input;
    output: Output;
}
/** A generic alias written bare, so every use applies its defaults. */
export type Tool<Input = any, Output = any> = FunctionTool<Input, Output> | DynamicTool<Input, Output>;
export type ToolSet = Record<string, Tool>;
export type ToolCallerDefinition = {
    type: "local";
    bind: (tools: ToolSet) => Tool;
} | {
    type: "provider";
    prepare: (options: string) => string;
};
export declare function toolCaller<T extends Tool>(tool: T, definition: ToolCallerDefinition): T;
